'use client';
import { useEffect, useRef, useState } from 'react';
import { animate, useInView, useReducedMotion } from 'motion/react';

/** Huge serif number that counts up on enter, with a small caps caption. */
export function StatBlock({ value, prefix = '', suffix = '', decimals = 0, label }: { value: number; prefix?: string; suffix?: string; decimals?: number; label: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { once: true, amount: 0.5 });
  const reduce = useReducedMotion();
  const [n, setN] = useState(reduce ? value : 0);

  useEffect(() => {
    if (!inView || reduce) return;
    const c = animate(0, value, { duration: 1.2, ease: [0.22, 1, 0.36, 1], onUpdate: setN });
    return () => c.stop();
  }, [inView, reduce, value]);

  return (
    <div ref={ref}>
      <p className="font-serif text-stat text-ink">{prefix}{n.toFixed(decimals)}{suffix}</p>
      <p className="mt-2 font-mono text-[10px] uppercase tracking-[.08em] text-ink-70">{label}</p>
    </div>
  );
}

/* Texture + halftone utilities */

/* Paper with dot grid */
.paper-dots {
  background-color: var(--bg);
  background-image: radial-gradient(var(--ink-06) 1px, transparent 1px);
  background-size: 24px 24px;
}

/* Film grain overlay — add <div class="grain" aria-hidden></div> as a fixed layer */
.grain {
  position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: .05;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
}

/* Flat halftone fill — apply to an element shaped like the object (clip-path / SVG mask) */
.halftone {
  background: #111;
  -webkit-mask-image: radial-gradient(circle at center, #000 38%, transparent 42%);
          mask-image: radial-gradient(circle at center, #000 38%, transparent 42%);
  -webkit-mask-size: 6px 6px;
          mask-size: 6px 6px;
}

/* Tonal halftone: dots fade along a gradient (light → dark) */
.halftone-tonal {
  position: relative;
  background: #111;
  -webkit-mask-image:
    radial-gradient(circle at center, #000 38%, transparent 42%),
    linear-gradient(135deg, transparent 0%, #000 70%);
  -webkit-mask-size: 6px 6px, 100% 100%;
  -webkit-mask-composite: source-in;
          mask-image:
    radial-gradient(circle at center, #000 38%, transparent 42%),
    linear-gradient(135deg, transparent 0%, #000 70%);
          mask-size: 6px 6px, 100% 100%;
          mask-composite: intersect;
}

/* Square-dot cloud around a hero subject (Contra) */
.dot-cloud {
  background-image: radial-gradient(var(--tint-1) 2.5px, transparent 3px);
  background-size: 10px 10px;
  -webkit-mask-image: radial-gradient(ellipse at 70% 60%, #000 0%, transparent 60%);
          mask-image: radial-gradient(ellipse at 70% 60%, #000 0%, transparent 60%);
  opacity: .7;
}

/* Data-text texture container */
.data-texture {
  position: absolute; inset: 0; overflow: hidden; pointer-events: none;
  font-family: var(--font-mono); font-size: 10px; line-height: 1.9; letter-spacing: .06em;
  text-transform: uppercase; color: var(--ink); opacity: .07; white-space: pre; user-select: none;
  -webkit-mask-image: radial-gradient(ellipse at center, #000 30%, transparent 75%);
          mask-image: radial-gradient(ellipse at center, #000 30%, transparent 75%);
}

/* Scrim for captions on paintings */
.scrim-bottom::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(to top, rgba(0,0,0,.45), transparent 45%);
}

/* Floating dark UI widget */
.ui-widget {
  background: color-mix(in srgb, var(--ui-dark) 94%, transparent);
  color: #F5F5F2; border: 1px solid rgba(255,255,255,.08);
  border-radius: 12px; box-shadow: var(--shadow-float);
